html:
{{ letter_head }}

{% set company_addr = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set company_address = frappe.get_doc("Address", company_addr) if company_addr else None %}
{% set customer_address = frappe.get_doc("Address", doc.customer_address) if doc.customer_address else None %}
{% set contact = frappe.get_doc("Contact", doc.contact_person) if doc.contact_person else None %}

{%- set _ns = namespace(qr_b64=None) %}
{%- if get_doc_qr_code is defined and get_doc_qr_code is callable %}
  {%- set _ns.qr_b64 = get_doc_qr_code(doc.doctype, doc.name) %}
{%- endif %}

{%- set item_count = doc.items | length %}
{%- set density_class = "" %}
{%- if item_count > 10 %}
  {%- set density_class = "ultra-compact" %}
{%- elif item_count > 6 %}
  {%- set density_class = "compact" %}
{%- endif %}

<style>
@page {
  size: A4;
  margin: 8mm 10mm 10mm 10mm;
}

.cgm-inv {
  font-family: Arial, Helvetica, sans-serif;
  color: #171717;
  font-size: 10.25px;
  line-height: 1.25;
  background: #fff;
}

.cgm-inv * {
  box-sizing: border-box;
}

.cgm-header {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 4px;
}

.cgm-header td {
  vertical-align: middle;
  padding: 0;
}

.cgm-header .title {
  margin: 0;
  font-size: 24px;
  font-weight: 800;
  letter-spacing: 1.5px;
  line-height: 1;
  text-transform: uppercase;
  color: #171717;
}

.cgm-meta-table {
  border-collapse: collapse;
  margin-left: auto;
}

.cgm-meta-table td {
  padding: 0;
  font-size: 10px;
  line-height: 1.3;
  white-space: nowrap;
}

.cgm-meta-label {
  color: #8b1a1a;
  font-weight: 700;
}

.cgm-meta-value {
  color: #171717;
  font-weight: 700;
  padding-left: 7px;
}

.cgm-meta-divider {
  color: #cfcfcf;
  padding: 0 12px !important;
  font-weight: 400;
}

.cgm-rule {
  border: none;
  border-top: 1px solid #e5e5e5;
  margin: 0 0 6px;
}

.cgm-parties {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 6px;
  page-break-inside: avoid;
}

.cgm-parties > tbody > tr > td {
  width: 50%;
  vertical-align: top;
  padding: 0 16px 0 0;
}

.cgm-parties > tbody > tr > td:last-child {
  padding: 0 0 0 16px;
}

.cgm-section-label {
  margin: 0 0 3px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: #8b1a1a;
}

.cgm-party-name {
  margin: 0 0 2px;
  font-size: 11.5px;
  font-weight: 700;
  color: #171717;
}

.cgm-party-line {
  margin: 0;
  font-size: 10px;
  color: #444;
  line-height: 1.3;
}

.cgm-shipment-wrap{
    margin: 8px 0 12px;
    padding: 6px 10px;
    background: #faf7f4;
    border: 1px solid #e7ddd5;
    border-left: 4px solid #8b1a1a;
    border-radius: 4px;
    page-break-inside: avoid;
}

.cgm-shipment{
    width:100%;
    border-collapse:collapse;
}

.cgm-shipment td{
    width:33.333%;
    padding:3px 10px;
    vertical-align:top;
    font-size:9px;
    line-height:1.2;
}

.cgm-ship-label{
    color:#8b1a1a;
    font-weight:700;
    margin-right:4px;
    white-space:nowrap;
}

.cgm-ship-value{
    color:#171717;
    font-weight:600;
}

.cgm-items {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 6px;
  table-layout: fixed;
}

.cgm-items thead {
  display: table-header-group;
}

.cgm-items tbody {
  display: table-row-group;
}

.cgm-items thead tr th {
  padding: 4px 8px;
  background: #8b1a1a;
  color: #fff;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.4px;
  text-align: left;
}

.cgm-items thead tr th.num {
  text-align: right;
}

.cgm-items tbody tr {
  page-break-inside: avoid;
  break-inside: avoid;
}

.cgm-items tbody tr td {
  padding:5px 8px;
  border:none;
  border-bottom:1px solid #f5f5f5;  
  color: #171717;
  font-size: 10px;
  line-height: 1.15;
  vertical-align: middle;
}

.cgm-items tbody tr td.num {
  text-align: right;
  white-space: nowrap;
}

.cgm-items tbody tr:nth-child(even) td {
  background: #fafafa;
}

.cgm-items tbody tr:last-child td {
  border-bottom: 1px solid #ddd;
}

.cgm-bottom {
  width: 100%;
  border-collapse: collapse;
  margin: 0;
  table-layout: fixed;
}

.cgm-bottom > tbody > tr > td {
  vertical-align: top;
  padding-top: 0;
  padding-bottom: 0;
}

.cgm-bottom .col-left {
  width: 52%;
  padding-right: 28px;
}

.cgm-bottom .col-right {
  width: 48%;
  padding-left: 6px;
}

.cgm-terms {
  margin: 0;
  padding: 0;
  color: #444;
  font-size: 10px;
  line-height: 1.35;
}

.cgm-terms .terms-title {
  display: block;
  margin: 0 0 3px;
  color: #8b1a1a;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.cgm-qr {
  width: 110px;
  margin-top: 6px;
  page-break-inside: avoid;
}

.cgm-qr img,
.cgm-qr svg {
  display: block;
  width: 110px;
  height: 110px;
}

.cgm-qr .qr-label {
  width: 110px;
  margin-top: 3px;
  color: #8b1a1a;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1px;
  text-align: center;
  text-transform: uppercase;
}

.cgm-totals {
  width: 100%;
  border-collapse: collapse;
  page-break-inside: avoid;
}

.cgm-totals td {
  padding: 4px 0;
  font-size: 11px;
}

.cgm-totals .t-label {
  color: #8b1a1a;
  font-weight: 700;
  text-align: left;
}

.cgm-totals .t-value {
  color: #171717;
  font-weight: 700;
  text-align: right;
  white-space: nowrap;
}

.cgm-totals .total-row td {
  padding-top: 6px;
  border-top: 1.5px solid #171717;
  color: #171717;
  font-size: 13px;
  font-weight: 800;
}

.cgm-totals .total-row .t-value {
  color: #171717;
  font-size: 14px;
  font-weight: 800;
}

.cgm-in-words {
  margin: 4px 0 0;
  color: #555;
  font-size: 9.5px;
  line-height: 1.3;
}
.cgm-inv-page {
  display: flex;
  flex-direction: column;
  min-height: calc(279mm - 45mm);
}

.cgm-doc-footer {
  margin-top: auto;
  padding-top: 2px;
}

/* ---------- COMPACT MODE: 7-10 items ---------- */
.cgm-inv.compact {
  font-size: 9.5px;
}
.cgm-inv.compact .cgm-header .title { font-size: 21px; }
.cgm-inv.compact .cgm-party-name { font-size: 11px; }
.cgm-inv.compact .cgm-party-line { font-size: 9.5px; }
.cgm-inv.compact .cgm-shipment-wrap { margin-bottom: 4px; }
.cgm-inv.compact .cgm-shipment > tbody > tr > td { padding: 4px 10px; }
.cgm-inv.compact .cgm-ship-field td { font-size: 8.5px; }
.cgm-inv.compact .cgm-items { margin-bottom: 4px; }
.cgm-inv.compact .cgm-items thead tr th { padding: 3px 7px; font-size: 9px; }
.cgm-inv.compact .cgm-items tbody tr td { padding: 2px 7px; font-size: 9.5px; line-height: 1.1; }
.cgm-inv.compact .cgm-terms { font-size: 9px; line-height: 1.25; }
.cgm-inv.compact .cgm-qr,
.cgm-inv.compact .cgm-qr img,
.cgm-inv.compact .cgm-qr svg { width: 90px; height: 90px; }
.cgm-inv.compact .cgm-qr .qr-label { width: 90px; }
.cgm-inv.compact .cgm-totals td { padding: 3px 0; font-size: 10px; }
.cgm-inv.compact .cgm-totals .total-row td { font-size: 12px; padding-top: 5px; }
.cgm-inv.compact .cgm-totals .total-row .t-value { font-size: 13px; }

/* ---------- ULTRA-COMPACT MODE: 11+ items ---------- */
.cgm-inv.ultra-compact {
  font-size: 8.75px;
}
.cgm-inv.ultra-compact .cgm-header { margin-bottom: 2px; }
.cgm-inv.ultra-compact .cgm-header .title { font-size: 18px; }
.cgm-inv.ultra-compact .cgm-rule { margin-bottom: 4px; }
.cgm-inv.ultra-compact .cgm-parties { margin-bottom: 4px; }
.cgm-inv.ultra-compact .cgm-party-name { font-size: 10px; }
.cgm-inv.ultra-compact .cgm-party-line { font-size: 8.75px; }
.cgm-inv.ultra-compact .cgm-section-label { margin-bottom: 2px; font-size: 8.5px; }
.cgm-inv.ultra-compact .cgm-shipment-wrap { margin-bottom: 3px; }
.cgm-inv.ultra-compact .cgm-shipment > tbody > tr > td { padding: 3px 8px; }
.cgm-inv.ultra-compact .cgm-ship-field td { font-size: 7.75px; }
.cgm-inv.ultra-compact .cgm-items { margin-bottom: 3px; }
.cgm-inv.ultra-compact .cgm-items thead tr th { padding: 2px 6px; font-size: 8.25px; }
.cgm-inv.ultra-compact .cgm-items tbody tr td { padding: 1px 6px; font-size: 8.75px; line-height: 1.05; }
.cgm-inv.ultra-compact .cgm-terms { font-size: 8.25px; line-height: 1.2; }
.cgm-inv.ultra-compact .cgm-terms .terms-title { font-size: 8.25px; margin-bottom: 2px; }
.cgm-inv.ultra-compact .cgm-qr,
.cgm-inv.ultra-compact .cgm-qr img,
.cgm-inv.ultra-compact .cgm-qr svg { width: 72px; height: 72px; }
.cgm-inv.ultra-compact .cgm-qr .qr-label { width: 72px; font-size: 7px; margin-top: 2px; }
.cgm-inv.ultra-compact .cgm-totals td { padding: 2px 0; font-size: 9px; }
.cgm-inv.ultra-compact .cgm-totals .total-row td { font-size: 11px; padding-top: 4px; }
.cgm-inv.ultra-compact .cgm-totals .total-row .t-value { font-size: 12px; }
.cgm-inv.ultra-compact .cgm-in-words { font-size: 8.25px; margin-top: 3px; }

@media print {
  .cgm-inv {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .cgm-items thead {
    display: table-header-group;
  }

  .cgm-items tbody tr {
    page-break-inside: avoid;
    break-inside: avoid;
  }

  .cgm-parties,
  .cgm-shipment-wrap,
  .cgm-qr,
  .cgm-totals {
    page-break-inside: avoid;
    break-inside: avoid;
  }
}
</style>

<div class="cgm-inv-page">
<div class="cgm-inv {{ density_class }}">

  <table class="cgm-header">
    <tr>
      <td style="width: 40%;">
        <h1 class="title">{% if doc.is_return %}Credit Note{% else %}Invoice{% endif %}</h1>
      </td>
      <td style="width: 60%;">
        <table class="cgm-meta-table">
          <tr>
            <td class="cgm-meta-label">Date</td>
            <td class="cgm-meta-value">
              {{ frappe.utils.format_date(doc.posting_date, "dd-MM-yyyy") }}
            </td>
            <td class="cgm-meta-divider">|</td>
            <td class="cgm-meta-label">{% if doc.is_return %}Credit Note No{% else %}Invoice No{% endif %}</td>
            <td class="cgm-meta-value">{{ doc.name }}</td>
            {% if doc.is_return and doc.return_against %}
            <td class="cgm-meta-divider">|</td>
            <td class="cgm-meta-label">Against Invoice</td>
            <td class="cgm-meta-value">{{ doc.return_against }}</td>
            {% endif %}
          </tr>
        </table>
      </td>
    </tr>
  </table>

  <hr class="cgm-rule">

  <table class="cgm-parties">
    <tr>
      <td>
        <div class="cgm-section-label">Consignee</div>
        <div class="cgm-party-name">{{ doc.customer_name }}</div>

        {% if customer_address %}
          {% if customer_address.address_line1 %}
            <div class="cgm-party-line">{{ customer_address.address_line1 }}</div>
          {% endif %}

          {% if customer_address.address_line2 %}
            <div class="cgm-party-line">{{ customer_address.address_line2 }}</div>
          {% endif %}

          {% if customer_address.city or customer_address.pincode %}
            <div class="cgm-party-line">
              {{ customer_address.city or "" }}{% if customer_address.city and customer_address.pincode %} - {% endif %}{{ customer_address.pincode or "" }}
            </div>
          {% endif %}

          {% if customer_address.country %}
            <div class="cgm-party-line">{{ customer_address.country }}</div>
          {% endif %}

          {% if customer_address.phone %}
            <div class="cgm-party-line">Phone: {{ customer_address.phone }}</div>
          {% elif doc.contact_mobile %}
            <div class="cgm-party-line">Phone: {{ doc.contact_mobile }}</div>
          {% elif contact and contact.mobile_no %}
            <div class="cgm-party-line">Phone: {{ contact.mobile_no }}</div>
          {% endif %}

          {% if customer_address.email_id %}
            <div class="cgm-party-line">Email: {{ customer_address.email_id }}</div>
          {% elif doc.contact_email %}
            <div class="cgm-party-line">Email: {{ doc.contact_email }}</div>
          {% elif contact and contact.email_id %}
            <div class="cgm-party-line">Email: {{ contact.email_id }}</div>
          {% endif %}

        {% elif doc.custom_consignee_address %}
          <div class="cgm-party-line">
            {{ doc.custom_consignee_address | replace("\n", "<br>") }}
          </div>

          {% if doc.contact_mobile %}
            <div class="cgm-party-line">Phone: {{ doc.contact_mobile }}</div>
          {% elif contact and contact.mobile_no %}
            <div class="cgm-party-line">Phone: {{ contact.mobile_no }}</div>
          {% endif %}

          {% if doc.contact_email %}
            <div class="cgm-party-line">Email: {{ doc.contact_email }}</div>
          {% elif contact and contact.email_id %}
            <div class="cgm-party-line">Email: {{ contact.email_id }}</div>
          {% endif %}

        {% elif doc.address_display %}
          <div class="cgm-party-line">{{ doc.address_display }}</div>

          {% if doc.contact_mobile %}
            <div class="cgm-party-line">Phone: {{ doc.contact_mobile }}</div>
          {% elif contact and contact.mobile_no %}
            <div class="cgm-party-line">Phone: {{ contact.mobile_no }}</div>
          {% endif %}

          {% if doc.contact_email %}
            <div class="cgm-party-line">Email: {{ doc.contact_email }}</div>
          {% elif contact and contact.email_id %}
            <div class="cgm-party-line">Email: {{ contact.email_id }}</div>
          {% endif %}

        {% else %}
          {% if doc.contact_mobile %}
            <div class="cgm-party-line">Phone: {{ doc.contact_mobile }}</div>
          {% elif contact and contact.mobile_no %}
            <div class="cgm-party-line">Phone: {{ contact.mobile_no }}</div>
          {% endif %}

          {% if doc.contact_email %}
            <div class="cgm-party-line">Email: {{ doc.contact_email }}</div>
          {% elif contact and contact.email_id %}
            <div class="cgm-party-line">Email: {{ contact.email_id }}</div>
          {% endif %}
        {% endif %}
      </td>

      <td>
        <div class="cgm-section-label">Invoice Address</div>
        <div class="cgm-party-name">{{ doc.company }}</div>

        {% if company_address %}
          {% if company_address.address_line1 %}
            <div class="cgm-party-line">{{ company_address.address_line1 }}</div>
          {% endif %}

          {% if company_address.address_line2 %}
            <div class="cgm-party-line">{{ company_address.address_line2 }}</div>
          {% endif %}

          {% if company_address.city or company_address.pincode %}
            <div class="cgm-party-line">
              {{ company_address.city or "" }}{% if company_address.city and company_address.pincode %} - {% endif %}{{ company_address.pincode or "" }}
            </div>
          {% endif %}

          {% if company_address.country %}
            <div class="cgm-party-line">{{ company_address.country }}</div>
          {% endif %}

          {% if company_address.phone %}
            <div class="cgm-party-line">Phone: {{ company_address.phone }}</div>
          {% endif %}

          {% if company_address.email_id %}
            <div class="cgm-party-line">Email: {{ company_address.email_id }}</div>
          {% endif %}

        {% elif doc.company_address_display %}
          <div class="cgm-party-line">{{ doc.company_address_display }}</div>
        {% endif %}
      </td>
    </tr>
  </table>

  <div class="cgm-shipment-wrap">
    <table class="cgm-shipment">
        <tr>
            <td>
                <span class="cgm-ship-label">Shipment:</span>
                <span class="cgm-ship-value">{{ doc.custom_project_name or doc.project or "" }}</span>
            </td>

            <td>
                <span class="cgm-ship-label">Country of Origin:</span>
                <span class="cgm-ship-value">{{ doc.custom_country_of_origin or "" }}</span>
            </td>

            <td>
                <span class="cgm-ship-label">Due Date:</span>
                <span class="cgm-ship-value">
                    {% if doc.due_date %}
                        {{ frappe.utils.format_date(doc.due_date, "dd-MM-yyyy") }}
                    {% endif %}
                </span>
            </td>
        </tr>

        <tr>
            <td>
                <span class="cgm-ship-label">CGM Ref No:</span>
                <span class="cgm-ship-value">{{ doc.custom_cgm_reference_no or "" }}</span>
            </td>
            <td>
                <span class="cgm-ship-label">Client Ref No:</span>
                <span class="cgm-ship-value">{{ doc.custom_client_reference_no or "" }}</span>
            </td>
        </tr>
    </table>
</div>
  <table class="cgm-items">
    <thead>
      <tr>
        <th style="width: 52%;">Item Descriptions</th>
        <th class="num" style="width: 12%;">Qty</th>
        <th class="num" style="width: 18%;">Rate</th>
        <th class="num" style="width: 18%;">Amount</th>
      </tr>
    </thead>
    <tbody>
      {% for item in doc.items %}
        <tr>
          <td>{{ item.description or item.item_name }}</td>
          <td class="num">{{ item.get_formatted("qty", doc) }}</td>
          <td class="num">{{ item.get_formatted("rate", doc) }}</td>
          <td class="num">{{ item.get_formatted("amount", doc) }}</td>
        </tr>
      {% endfor %}
    </tbody>
  </table>

  <table class="cgm-bottom">
    <tr>
      <td class="col-left">
        {% if doc.terms %}
          <div class="cgm-terms">
            <span class="terms-title">Terms</span>
            {{ doc.terms }}
          </div>
        {% endif %}

        <div class="cgm-qr">
          {% if _ns.qr_b64 %}
            <img
              src="data:image/png;base64,{{ _ns.qr_b64 }}"
              alt="Scan to Verify"
              style="display: block; object-fit: contain;"
            >
          {% else %}
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 80 80"
              style="display: block;"
            >
              <rect width="80" height="80" fill="white" stroke="#e0e0e0" stroke-width="0.5"/>
              <rect x="4" y="4" width="28" height="28" fill="none" stroke="#8b1a1a" stroke-width="2.5" rx="2"/>
              <rect x="9" y="9" width="18" height="18" fill="#8b1a1a" rx="1"/>
              <rect x="48" y="4" width="28" height="28" fill="none" stroke="#8b1a1a" stroke-width="2.5" rx="2"/>
              <rect x="53" y="9" width="18" height="18" fill="#8b1a1a" rx="1"/>
              <rect x="4" y="48" width="28" height="28" fill="none" stroke="#8b1a1a" stroke-width="2.5" rx="2"/>
              <rect x="9" y="53" width="18" height="18" fill="#8b1a1a" rx="1"/>
              <rect x="40" y="40" width="6" height="6" fill="#8b1a1a"/>
              <rect x="49" y="40" width="6" height="6" fill="#8b1a1a"/>
              <rect x="58" y="40" width="6" height="6" fill="#8b1a1a"/>
              <rect x="67" y="40" width="6" height="6" fill="#8b1a1a"/>
              <rect x="40" y="49" width="6" height="6" fill="#8b1a1a"/>
              <rect x="58" y="49" width="6" height="6" fill="#8b1a1a"/>
              <rect x="40" y="58" width="6" height="6" fill="#8b1a1a"/>
              <rect x="49" y="58" width="6" height="6" fill="#8b1a1a"/>
              <rect x="67" y="58" width="6" height="6" fill="#8b1a1a"/>
              <rect x="40" y="67" width="6" height="6" fill="#8b1a1a"/>
              <rect x="58" y="67" width="6" height="6" fill="#8b1a1a"/>
              <rect x="67" y="67" width="6" height="6" fill="#8b1a1a"/>
            </svg>
          {% endif %}
          <div class="qr-label">Scan to Verify</div>
        </div>
      </td>

      <td class="col-right">
        <table class="cgm-totals">
          <tr>
            <td class="t-label">Subtotal</td>
            <td class="t-value">{{ doc.get_formatted("net_total") }}</td>
          </tr>

          {% set vat_shown = namespace(ok=false) %}
          {% for tax in doc.taxes or [] %}
            {% if tax.tax_amount %}
              <tr>
                <td class="t-label">{{ tax.description or "VAT" }}</td>
                <td class="t-value">{{ tax.get_formatted("tax_amount") }}</td>
              </tr>
              {% set vat_shown.ok = true %}
            {% endif %}
          {% endfor %}

          {% if not vat_shown.ok %}
            <tr>
              <td class="t-label">VAT</td>
              <td class="t-value"></td>
            </tr>
          {% endif %}

          <tr class="total-row">
            <td class="t-label">Total</td>
            <td class="t-value">{{ doc.get_formatted("grand_total") }}</td>
          </tr>
        </table>

        {% if doc.in_words %}
          <p class="cgm-in-words">
            <strong>In Words:</strong> {{ doc.in_words }}
          </p>
        {% endif %}
